def entry_snapshot():
    """Literal A11 state, deliberately not generated by a ledger implementation."""
    f=v.a11_fixture();cfg,records=f.seal();unit=f.unit("o",0,10)
    ob=dict(instrument_id=v.BTC,obligation_id="fee-o",kind="fee",origin_id="o",latest_revision=1,
            T_usdt="-0.2495",B_usdt="-0.2495",P_usdt="0",A_usdt="0",L_usdt="0",
            allocation_refs=[f.alloc("fee-o",[(unit,"-0.2495")])[0]["allocation_id"]],
            posting_refs=[dict(instrument_id=v.BTC,record_type="Posting",record_id="p-o",revision=1)],null_reasons={})
    b=dict(as_of_us=10*v.U,knowledge_cutoff_us=10*v.U,view="as_known",
           **v.balance("9999.7505","0","0","0","9999.7505","9999.7505"),
           reserved_margin_usdt="0",reserved_fees_usdt="0",actual_available_margin_usdt=None,
           new_risk_supported=True,reductions_supported=True,valuation_refs=["m10"],reserve_refs=["reserve-BTC_USDT"],
           null_reasons={"actual_available_margin_usdt":"NOT_MODELED"})
    lot=dict(lot_id="lot:o",episode_id="episode:o",instrument_id=v.BTC,opening_fill_id="o",opened_at_us=10*v.U,
             direction="long",initial_contracts=10,remaining_contracts=10,entry_price="49900",multiplier="0.001",
             live_ranges=[unit],closed_slice_ids=[])
    s=dict(namespace=v.NS,schema_version=1,profile=v.PROFILE,ledger_id="qr007",trajectory_id="trajectory",scenario_id="literal",
           view="as_known",as_of_us=10*v.U,knowledge_cutoff_us=10*v.U,
           causal_policy_sha256=v.digest({k:x for k,x in cfg.items() if k!="source_manifest"}),
           balances=b,lots=[lot],closed_slices=[],obligations=[ob],coverage_issues=[],null_reasons={})
    s["state_sha256"]=v.digest(s)
    return cfg,records,s


def rehash(snapshot):
    snapshot["state_sha256"]=v.digest({k:x for k,x in snapshot.items() if k!="state_sha256"})


class CheckerFinancialTests(unittest.TestCase):
    def test_readiness_cannot_claim_future_or_blocked_completion(self):
        complete=dict(episode_id="episode:o",as_of_us=10*v.U,natural_exit_at_us=3*v.U,
                      status="complete",complete_at_us=10*v.U,assertion_refs=[],
                      blocking_reasons=[],null_reasons={})
        v.check_readiness(complete)
        for change in ({"complete_at_us":11*v.U}, {"natural_exit_at_us":11*v.U},
                       {"blocking_reasons":["UNSETTLED_OBLIGATION"]},
                       {"status":"immature"}):
            bad=copy.deepcopy(complete);bad.update(change)
            with self.subTest(change=change),self.assertRaises(v.CheckError):v.check_readiness(bad)
        for status,reason in (("open","OPEN_EPISODE"),("immature","UNSETTLED_OBLIGATION"),
                              ("invalid","INVALID_ASSERTION_AUTHORITY")):
            value=copy.deepcopy(complete);value.update(status=status,complete_at_us=None,
                blocking_reasons=[reason],null_reasons={"complete_at_us":reason})
            if status=="open":value["natural_exit_at_us"]=None;value["null_reasons"]["natural_exit_at_us"]="OPEN_EPISODE"
            v.check_readiness(value)

    def test_literal_a11_snapshot_and_source_binding(self):
        cfg,records,s=entry_snapshot()
        v.check_snapshot(s,cfg,v.balance("9999.7505","0","0","0","9999.7505","9999.7505"),{"lot:o":10},records)

    def test_coordinated_cash_equity_budget_tamper_rehashed(self):
        cfg,records,s=entry_snapshot()
        for key in ("cash_usdt","economic_equity_usdt","simulated_budget_usdt"):s["balances"][key]="10000.7505"
        rehash(s)
        with self.assertRaisesRegex(v.CheckError,"cash differs"):
            v.check_snapshot(s,cfg,records=records)

    def test_coordinated_T_B_tamper_rehashed(self):
        cfg,records,s=entry_snapshot()
        s["obligations"][0]["T_usdt"]=s["obligations"][0]["B_usdt"]="0.2495"
        rehash(s)
        with self.assertRaisesRegex(v.CheckError,"T differs"):
            v.check_snapshot(s,cfg,records=records)

    def test_unrelated_positive_negative_claims_cannot_net(self):
        cfg,_,s=entry_snapshot()
        a=copy.deepcopy(s["obligations"][0]);a.update(obligation_id="a",T_usdt="20",B_usdt="0",P_usdt="20",A_usdt="20",L_usdt="0")
        l=copy.deepcopy(a);l.update(obligation_id="l",T_usdt="-30",P_usdt="-30",A_usdt="0",L_usdt="30")
        s["obligations"]=[a,l];s["balances"].update(receivables_usdt="0",liabilities_usdt="10",economic_equity_usdt="9989.7505",simulated_budget_usdt="9989.7505")
        rehash(s)
        with self.assertRaisesRegex(v.CheckError,"separate aggregate"):
            v.check_snapshot(s,cfg)

    def test_unknown_T_cannot_be_zeroed_in_totals(self):
        cfg,_,s=entry_snapshot();o=s["obligations"][0]
        for k in ("T_usdt","P_usdt","A_usdt","L_usdt"):o[k]=None;o["null_reasons"][k]="UNKNOWN_OBLIGATION_TOTAL"
        rehash(s)
        with self.assertRaisesRegex(v.CheckError,"unknown aggregate hidden"):
            v.check_snapshot(s,cfg)

    def test_false_null_reason_rejected(self):
        cfg,_,s=entry_snapshot();s["balances"]["null_reasons"]["actual_available_margin_usdt"]="UNKNOWN_AMOUNT";rehash(s)
        with self.assertRaisesRegex(v.CheckError,"actual margin claim"):v.check_snapshot(s,cfg)

    def test_nested_missing_extra_and_wrong_type_rejected_after_rehash(self):
        cfg,_,base=entry_snapshot()
        def drop(s):s["lots"][0].pop("remaining_contracts")
        def extra(s):s["balances"]["fake_margin"]="100"
        def boolean(s):s["lots"][0]["remaining_contracts"]=True
        def floating(s):s["balances"]["cash_usdt"]=9999.7505
        def reason(s):s["balances"]["null_reasons"]={}
        for mutate in (drop,extra,boolean,floating,reason):
            with self.subTest(mutate=mutate.__name__):
                s=copy.deepcopy(base);mutate(s);rehash(s)
                with self.assertRaises(v.CheckError):v.check_snapshot(s,cfg)

    def test_unknown_posting_preserves_cash_and_null_deltas(self):
        entry=dict(entry_id="1"*64,source_key=dict(instrument_id=v.BTC,record_type="Posting",record_id="p",revision=1),
                   transition="cash_posting",obligation_id="fund-s",allocation_id=None,episode_id="episode:o",
                   economic_at_us=2*v.U,available_at_us=10*v.U,cash_delta_usdt="-0.02",realized_pnl_usdt="0",
                   pending_delta_usdt=None,receivable_delta_usdt=None,liability_delta_usdt=None,
                   null_reasons=dict(allocation_id="AGGREGATE_OBLIGATION",pending_delta_usdt="UNKNOWN_OBLIGATION_TOTAL",
                                     receivable_delta_usdt="UNKNOWN_OBLIGATION_TOTAL",liability_delta_usdt="UNKNOWN_OBLIGATION_TOTAL"))
        v.check_entry(entry)
        bad=copy.deepcopy(entry);bad["cash_delta_usdt"]="0"
        with self.assertRaisesRegex(v.CheckError,"cash separation"):v.check_entry(bad)
        bad=copy.deepcopy(entry);bad["pending_delta_usdt"]="0"
        with self.assertRaises(v.CheckError):v.check_entry(bad)

    def test_fee_claim_cannot_emit_cash(self):
        e=dict(entry_id="1"*64,source_key=dict(instrument_id=v.BTC,record_type="Fill",record_id="o",revision=1),
               transition="fee_claim",obligation_id="fee-o",allocation_id=None,episode_id="episode:o",
               economic_at_us=v.U,available_at_us=v.U,cash_delta_usdt="-0.25",realized_pnl_usdt="0",
               pending_delta_usdt="-0.25",receivable_delta_usdt="0",liability_delta_usdt="0.25",
               null_reasons={"allocation_id":"AGGREGATE_OBLIGATION"})
        with self.assertRaisesRegex(v.CheckError,"cash separation"):v.check_entry(e)

    def test_Fraction_FIFO_partial_and_reversal_oracle(self):
        f=v.Fixture(fee="0",multiplier="1");f.fill("o",v.U,10,"100");f.fill("c",2*v.U,-6,"102");f.fill("r",3*v.U,-10,"103");f.fill("end",4*v.U,6,"101")
        result=v.reference_closures(f.records)
        self.assertEqual([result[v.record_key(f.records[i])] for i in (1,2,3)],[[Fraction(12)],[Fraction(12)],[Fraction(12)]])

    def test_decimal_oracle_not_ambient_context(self):
        from decimal import localcontext
        with localcontext() as c:
            c.prec=2
            self.assertEqual(v.finite_decimal(Fraction(10)*Fraction("0.001")*49900*Fraction("0.0005")),"0.2495")
            self.assertEqual(v.finite_decimal(Fraction("-.02")-Fraction("-.05")),"0.03")
        for text in ("+0.000","-0.0","0"):self.assertEqual(v.decimal_text(text),"0")
        for bad in (True,1.0,"NaN","1e3","01",".1"):
            with self.assertRaises(v.CheckError):v.decimal_text(bad)

    def test_rehashed_fixture_future_fact_changes_manifest_only(self):
        f,_=v.flat_funding(initial_available=20*v.U,initial_post=False);a,ra=f.seal()
        revised=copy.deepcopy(f);r=revised.records[-1];r["cumulative_signed_total_usdt"]="-0.08";r["allocations"][0]["signed_cash_usdt"]="-0.08"
        b,rb=revised.seal()
        self.assertNotEqual(a["source_manifest"],b["source_manifest"])
        self.assertNotEqual(ra[0]["source_refs"],rb[0]["source_refs"])
        self.assertEqual({k:x for k,x in a.items() if k!="source_manifest"},{k:x for k,x in b.items() if k!="source_manifest"})

    def test_fixture_strict_shapes_and_hashes(self):
        f,_=v.flat_funding();f.assertion(10*v.U,[("fee-o",1),("fee-c",1),("fund-s",1)],["p1"])
        for fixture in (v.a11_fixture(),v.a11_fixture(True),f):
            cfg,records=fixture.seal()
            for row,record in zip(cfg["source_manifest"]["rows"],records):
                v.shape("Record",record)
                self.assertEqual(row["payload_sha256"],v.independent_content(record))
                self.assertEqual(record["source_refs"][0]["manifest_sha256"],v.digest(cfg["source_manifest"]))


class CheckerBoundariesTests(unittest.TestCase):
    def test_prepared_has_no_producer_pass_or_fit(self):
        report=v.prepared_report()
        self.assertEqual(report["status"],"PREPARED_NOT_EXECUTED")
        self.assertEqual(report["totals"],dict(prepared=21,passed=0,failed=0,not_executed=21))
        self.assertEqual(len(report["criteria"]),34)
        self.assertIsNone(report["target"])
        self.assertFalse(report["producer_executed"])
        self.assertEqual(report["model_fits"],0)
        self.assertIn("A26",v.DEFERRED)
        self.assertEqual(len({r["case_id"] for r in report["cases"]}),21)

    def test_B1_prevents_candidate_execution_until_owner_patch(self):
        self.assertTrue(v.PENDING_CONTRACTS)
        with self.assertRaisesRegex(v.CheckError,"amendment pending"):
            v.load_target("not-read.py","0"*64,"0"*40,"not-read.md")
        with self.assertRaisesRegex(v.CheckError,"amendment pending"):
            v.execute_cases(object(),{})

    def test_offline_guard_and_restoration(self):
        previous=socket.create_connection
        with v.offline():
            with self.assertRaisesRegex(v.CheckError,"Network disabled"):socket.create_connection(("invalid.example",443))
            with socket.socket() as s:
                with self.assertRaises(v.CheckError):s.connect(("127.0.0.1",1))
                with self.assertRaises(v.CheckError):s.connect_ex(("127.0.0.1",1))
        self.assertIs(socket.create_connection,previous)

    def test_new_atomic_output_and_overwrite_protection(self):
        with tempfile.TemporaryDirectory() as d:
            path=Path(d).resolve()/"report.json";v.write_result(path,v.prepared_report());original=path.read_bytes()
            self.assertEqual(json.loads(original)["status"],"PREPARED_NOT_EXECUTED")
            with self.assertRaises(v.CheckError):v.write_result(path,{"status":"changed"})
            self.assertEqual(path.read_bytes(),original)
            self.assertEqual(sorted(p.name for p in Path(d).resolve().iterdir()),["report.json"])

    def test_failed_publish_cleans_own_temp_and_never_creates_success(self):
        with tempfile.TemporaryDirectory() as d:
            path=Path(d).resolve()/"report.json"
            with patch.object(v.os,"link",side_effect=OSError("simulated publish failure")):
                with self.assertRaises(OSError):v.write_result(path,{"status":"success"})
            self.assertFalse(path.exists());self.assertEqual(list(Path(d).resolve().iterdir()),[])

    def test_symlink_output_and_nonfinite_payload_refused(self):
        with tempfile.TemporaryDirectory() as d:
            original=Path(d).resolve()/"old.json";original.write_text("preserve");link=Path(d).resolve()/"link.json";link.symlink_to(original)
            with self.assertRaises(v.CheckError):v.write_result(link,{})
            self.assertEqual(original.read_text(),"preserve")
            with self.assertRaises(ValueError):v.write_result(Path(d).resolve()/"nan.json",{"x":float("nan")})
            self.assertFalse((Path(d).resolve()/"nan.json").exists())

    def test_explicit_artifact_corruption_even_with_new_hash(self):
        _,_,snapshot=entry_snapshot()
        with tempfile.TemporaryDirectory() as d:
            path=Path(d).resolve()/"snapshot.json";path.write_text(json.dumps(snapshot))
            self.assertEqual(v.inspect_snapshot_artifact(path,"entry")["status"],"PASS_ONE_LITERAL_SNAPSHOT_ONLY")
            for k in ("cash_usdt","economic_equity_usdt","simulated_budget_usdt"):snapshot["balances"][k]="10000.7505"
            rehash(snapshot);path.write_text(json.dumps(snapshot))
            with self.assertRaises(v.CheckError):v.inspect_snapshot_artifact(path,"entry")

    def test_duplicate_keys_and_nonfinite_rejected(self):
        for data in ('{"a":1,"a":2}','{"x":NaN}','{"x":Infinity}'):
            with self.assertRaises(v.CheckError):v.strict_json(data)

    def test_cli_prepare_does_not_load_or_scan_target(self):
        with patch.object(v,"load_target",side_effect=AssertionError("must not load")),redirect_stdout(io.StringIO()) as output:
            self.assertEqual(v.main(["--prepare"]),0)
        report=json.loads(output.getvalue());self.assertEqual(report["totals"]["passed"],0)


if __name__=="__main__":unittest.main()
